{"file_path":"src/utils.js","content":"/** Small helpers shared by pointer resolution and patch application. */

/**
 * Define an own, enumerable, writable, configurable property.
 *
 * Using this instead of `obj[key] = value` avoids the `__proto__` setter
 * that a normal assignment would trigger on a plain object, so a key named
 * `__proto__` becomes an ordinary own property instead of changing the
 * object's prototype.
 *
 * @param {object} object target object
 * @param {string} key property name
 * @param {unknown} value property value
 */
export function setOwn(object, key, value) {
  Object.defineProperty(object, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/**
 * @param {unknown} value candidate
 * @returns {boolean} true for a non-null, non-array object
 */
export function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Name a value's JSON type for an error message.
 *
 * @param {unknown} value the value to name
 * @returns {string} 'null', 'array', or the result of `typeof`
 */
export function typeName(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

/**
 * Deep-copy a value while checking it is JSON data, using `setOwn` so keys
 * such as `__proto__` end up as ordinary own properties.
 *
 * @param {unknown} value value to copy
 * @param {string} message error message to use if it is not JSON data
 * @returns {unknown} an independent deep copy
 */
export function cloneJSON(value, message) {
  if (value === null) return null;
  const type = typeof value;
  if (type === 'string' || type === 'boolean') return value;
  if (type === 'number') {
    if (!Number.isFinite(value)) throw new Error(message);
    return value;
  }
  if (Array.isArray(value)) return value.map((item) => cloneJSON(item, message));
  if (type === 'object') {
    const result = {};
    for (const key of Object.keys(value)) setOwn(result, key, cloneJSON(value[key], message));
    return result;
  }
  throw new Error(message);
}

/**
 * Compare two JSON values structurally: array order matters, object member
 * order does not, and there is no type coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether they represent the same JSON data
 */
export function deepEqualJSON(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    return a.length === b.length && a.every((item, index) => deepEqualJSON(item, b[index]));
  }
  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every(
      (key) => Object.prototype.hasOwnProperty.call(b, key) && deepEqualJSON(a[key], b[key]),
    );
  }
  return false;
}

/**
 * @param {string[]} a tokens
 * @param {string[]} b tokens
 * @returns {boolean} whether the two token arrays are equal element by element
 */
export function arraysEqual(a, b) {
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

/**
 * @param {string[]} a candidate prefix tokens
 * @param {string[]} b candidate child tokens
 * @returns {boolean} whether `a` is a proper (strict) prefix of `b`
 */
export function isProperPrefix(a, b) {
  return a.length < b.length && a.every((value, index) => value === b[index]);
}
"}

